ALTER TABLE ai_voice_clone ADD COLUMN remaining_training_times INT NULL, ADD COLUMN provider_status INT NULL, ADD COLUMN quota_checked_at DATETIME NULL, ADD COLUMN demo_audio_url VARCHAR(2048) NULL;
UPDATE ai_model_provider SET fields=JSON_ARRAY_APPEND(CAST(fields AS JSON),'$',JSON_OBJECT('key','voice_clone_api_key','type','string','label','复刻2.0新版API Key（选填；不填使用AppID/Access Token）'),'$',JSON_OBJECT('key','voice_clone_resource_id','type','string','label','复刻Resource ID（选填，默认seed-icl-2.0）')) WHERE provider_code='huoshan_double_stream' AND JSON_SEARCH(CAST(fields AS JSON),'one','voice_clone_api_key') IS NULL;
